<script setup lang="ts">
import { ref, computed } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import KnowledgeGraph from '../../components/KnowledgeGraph.vue'
import KnowledgeLearningView from '../../components/KnowledgeLearningView.vue'
import Formula from '../../components/Formula.vue'
import Icon from '../../components/Icon.vue'
import { nodes, relations, chapters, resources, questions, resourceTypeIcon, resourceTypeLabel, learningPath } from '../../data/course'
import { navigate, learnedNodeIds, visitNode, openResource, progress } from '../../store'
const selectedId = ref('first-law'), chapterFilter = ref(''), search = ref(''), labOpen = ref(false)
const viewMode = ref<'graph' | 'chapter' | 'prerequisite'>('graph')
const viewOptions = [
  { id: 'graph' as const, label: '关联图谱' },
  { id: 'chapter' as const, label: '章节学习路径' },
  { id: 'prerequisite' as const, label: '先修顺序' },
]
const hot = ref(600), cold = ref(300)
const efficiency = computed(() => (1 - cold.value / hot.value) * 100)
const selected = computed(() => nodes.find(n => n.id === selectedId.value) || nodes[0])
const selectedChapter = computed(() => chapters.find(c => c.id === selected.value.chapterId))
const linkedResources = computed(() => resources.filter(r => r.nodeIds.includes(selectedId.value)))
const linkedQuestions = computed(() => questions.filter(q => q.nodeIds.includes(selectedId.value)))
const neighbours = computed(() => relations.filter(r => r.source === selectedId.value || r.target === selectedId.value).map(r => ({ ...r, node: nodes.find(n => n.id === (r.source === selectedId.value ? r.target : r.source)), before: r.target === selectedId.value })))
onLoad((options) => { if (options?.node && nodes.some(n => n.id === options.node)) selectedId.value = options.node; if (options?.chapter) chapterFilter.value = options.chapter; if (options?.q) { search.value = options.q; const match = nodes.find(n => n.title.includes(options.q)); if (match) selectedId.value = match.id } visitNode(selectedId.value) })
function selectNode(id: string) { selectedId.value = id; visitNode(id) }
function hotChange(event: Event) { hot.value = Number((event.target as HTMLInputElement).value); if (cold.value >= hot.value) cold.value = hot.value - 50 }
function coldChange(event: Event) { cold.value = Math.min(Number((event.target as HTMLInputElement).value), hot.value - 50) }
</script>
<template><AppShell active="graph" title="知识图谱"><div class="page-heading"><div><h1>把知识点，连接成理解</h1><p>沿着概念之间的联系，找到属于你的学习路径。</p></div><span class="tag"><Icon name="graph" :size="13" />{{ nodes.length }} 个精选知识点 · {{ relations.length }} 条关联</span></div>
  <div class="view-switcher" role="group" aria-label="切换知识图谱视图"><button v-for="view in viewOptions" :key="view.id" type="button" class="view-option" :class="{ active: viewMode === view.id }" :aria-pressed="viewMode === view.id" @click="viewMode = view.id">{{ view.label }}</button></div>
  <div class="graph-toolbar"><div class="local-search"><Icon name="search" :size="16" /><input v-model="search" placeholder="搜索知识点…" aria-label="筛选图谱知识点" /><button v-if="search" class="icon-button" aria-label="清除图谱搜索" @click="search = ''"><Icon name="close" :size="14" /></button></div><select v-model="chapterFilter" class="filter-select" aria-label="选择图谱章节"><option value="">全部课程章节</option><option v-for="chapter in chapters" :key="chapter.id" :value="chapter.id">{{ chapter.number }} · {{ chapter.title }}</option></select><span class="graph-toolbar-hint"><i></i> 点击节点，探索知识与资源</span><button class="text-link" @click="labOpen = true"><Icon name="flask" :size="16" />卡诺热机小实验</button></div>
  <div class="graph-layout"><div class="graph-main"><KnowledgeGraph v-if="viewMode === 'graph'" :nodes="nodes" :relations="relations" :chapters="chapters" :selected-id="selectedId" :completed-ids="learnedNodeIds" :chapter-filter="chapterFilter" :search="search" @select="selectNode" /><KnowledgeLearningView v-else :key="viewMode" :nodes="nodes" :relations="relations" :chapters="chapters" :learning-path="learningPath" :mode="viewMode === 'prerequisite' ? 'prerequisite' : 'chapter'" :selected-id="selectedId" :completed-ids="learnedNodeIds" :chapter-filter="chapterFilter" :search="search" @select="selectNode" /><div class="graph-bottom-note"><Icon name="link" :size="15" /><p><strong>理解关联，也理解顺序。</strong>「前置」指向后续知识，「应用」连接原理与工程场景。章节与关系可随课程内容继续完善。</p></div></div>
    <aside class="node-detail panel" aria-live="polite"><div class="detail-chapter"><span :style="{ color: selectedChapter?.color }">CHAPTER {{ selectedChapter?.number }}</span><span class="tag" :class="{ amber: selected.level === '进阶' }">{{ selected.level }}</span></div><h2>{{ selected.title }}</h2><div class="detail-labels"><span>{{ selectedChapter?.title }}</span><span v-if="learnedNodeIds.includes(selected.id)" class="learned-badge"><Icon name="check" :size="12" />已学</span></div><p class="node-summary">{{ selected.summary }}</p><Formula :value="selected.formula" :note="selected.formulaNote" /><div class="detail-section"><div class="section-title"><h3>关联学习资源</h3><span>{{ linkedResources.length }} 项</span></div><button v-for="resource in linkedResources" :key="resource.id" class="detail-resource" @click="openResource(resource.id)"><span class="detail-resource-icon" :class="{slides:resource.type === 'slides', external:resource.type === 'external'}"><Icon :name="resourceTypeIcon[resource.type]" :size="16" /></span><span><strong>{{ resource.title }}</strong><small>{{ resourceTypeLabel[resource.type] }} · {{ resource.duration }}<template v-if="resource.source"> · {{ resource.source }}</template></small></span><Icon v-if="progress.completed.includes(resource.id)" name="check" :size="14" /><Icon v-else name="chevron" :size="13" /></button><p v-if="!linkedResources.length" class="detail-empty">该知识点的正式资源待补充，可先探索关联概念。</p></div><div class="detail-section"><div class="section-title"><h3>知识关联</h3><span>{{ neighbours.length }} 项</span></div><div class="related-nodes"><button v-for="(item,index) in neighbours" :key="index" @click="selectNode(item.node!.id)"><span>{{ item.before && item.type === '前置' ? '前置知识' : item.type === '前置' ? '后续知识' : item.type }}</span>{{ item.node?.title }}<Icon name="chevron" :size="12" /></button></div></div><button class="button primary full-width" :disabled="!linkedQuestions.length" @click="navigate('practice', { node: selected.id })"><Icon name="edit" :size="16" />{{ linkedQuestions.length ? '练一练 · ' + linkedQuestions.length + ' 道关联习题' : '关联习题待补充' }}</button><button v-if="selected.id === 'carnot'" class="button secondary full-width lab-entry" @click="labOpen = true"><Icon name="flask" :size="16" />动手探索卡诺效率</button></aside></div>
  <div v-if="labOpen" class="modal-backdrop" @click.self="labOpen = false"><section class="modal lab-modal" role="dialog" aria-modal="true" aria-labelledby="lab-title"><button class="modal-close icon-button" aria-label="关闭交互实验" @click="labOpen = false"><Icon name="close" /></button><span class="eyebrow">THERMODYNAMICS LAB</span><h2 id="lab-title">热源温度，怎样影响效率？</h2><p class="muted">拖动温度滑块，观察理想可逆热机的效率上限。</p><div class="lab-visual"><div class="heat-source"><span>高温热源 Tₕ</span><strong>{{ hot }}<small> K</small></strong></div><div class="heat-engine"><span class="energy-arrow">↓ Qₕ</span><span class="engine-circle">热机</span><span class="work-arrow">→ W</span><span class="energy-arrow">↓ Q𝚌</span></div><div class="cold-source"><span>低温热源 T𝚌</span><strong>{{ cold }}<small> K</small></strong></div></div><div class="lab-sliders"><label>高温热源 <strong>{{ hot }} K</strong><input type="range" min="400" max="1000" step="10" :value="hot" @input="hotChange" /></label><label>低温热源 <strong>{{ cold }} K</strong><input type="range" min="200" :max="Math.min(500,hot-50)" step="10" :value="cold" @input="coldChange" /></label></div><div class="lab-result"><span>η = 1 − T𝚌 / Tₕ</span><strong>{{ efficiency.toFixed(1) }}<small>%</small></strong><p>每吸收 100 kJ 热量，最多输出 {{ efficiency.toFixed(1) }} kJ 功。</p></div><div class="soft-note">适用条件：两个恒温热源之间的可逆卡诺热机；温度为绝对温度 K，且 Tₕ &gt; T𝚌 &gt; 0。实际不可逆热机的效率低于这一上限。</div></section></div>
</AppShell></template>
<style scoped>
