on.slides{color:#b09971;background:#f7f0e5}.detail-resource-icon.external{color:#6f7bb0;background:#eceff7}.detail-resource>span:nth-child(2){flex:1;min-width:0}.detail-resource strong{font-size:10px;line-height:1.7;font-weight:500;display:block}.detail-resource small{font-size:9px;color:#a1ac98;display:block;margin-top:3px}.detail-resource>svg{color:#a7b79e}.detail-empty{padding:10px 0;color:#a0ac98;font-size:10px;line-height:1.9}.related-nodes{display:flex;flex-direction:column;gap:7px}.related-nodes button{display:flex;align-items:center;gap:7px;font-size:10px;padding:8px 9px;background:#f6f8f3;border-radius:5px;text-align:left}.related-nodes button>span{color:#a3af99;font-size:8px}.related-nodes button>svg{margin-left:auto;color:#a5b79b}.lab-entry{margin-top:9px}.lab-modal{max-width:510px;padding:31px}.lab-modal h2{font-size:23px;font-weight:600;margin:14px 0 8px}.lab-visual{margin:24px 0;display:flex;flex-direction:column;align-items:center}.heat-source,.cold-source{border-radius:8px;padding:10px 24px;display:flex;justify-content:space-between;width:260px;align-items:center;background:#f7eedd;color:#aa8b5e}.cold-source{background:#e9f1f1;color:#6a9698}.heat-source>span,.cold-source>span{font-size:11px}.heat-source strong,.cold-source strong{font-size:20px;font-weight:500}.heat-source small,.cold-source small{font-size:11px}.heat-engine{display:flex;flex-direction:column;align-items:center;position:relative;gap:6px;padding:7px 0}.energy-arrow{font-size:11px;color:#9ca28b}.engine-circle{display:grid;place-items:center;border:1px solid #bdd4bc;background:#eef5e8;width:55px;height:55px;border-radius:50%;font-size:12px;color:#699461}.work-arrow{position:absolute;left:75px;top:45px;white-space:nowrap;color:#89a77f;font-size:13px}.lab-sliders{display:grid;grid-template-columns:1fr 1fr;gap:24px}.lab-sliders label{font-size:11px;color:#8da080}.lab-sliders strong{float:right;color:#6b8c59}.lab-sliders input{width:100%;margin-top:12px;accent-color:#659b62}.lab-result{text-align:center;padding:20px 0}.lab-result>span{display:block;color:#a2ae93;font-family:Georgia;font-size:16px}.lab-result>strong{display:block;color:#4b804b;font-size:42px;font-weight:500;margin:9px 0}.lab-result small{font-size:20px}.lab-result>p{color:#8c9d7c;font-size:11px}
@media(max-width:1200px){.graph-layout{grid-template-columns:minmax(0,1fr) 270px;gap:15px}.node-detail{padding:20px 16px}.graph-toolbar-hint{display:none}.graph-toolbar{gap:9px}.graph-toolbar .local-search input{width:140px}}
@media(max-width:1120px){.graph-layout{grid-template-columns:1fr}.node-detail{padding:25px;display:grid;grid-template-columns:1fr 1fr;column-gap:24px}.detail-chapter,.node-detail h2,.detail-labels,.node-summary{grid-column:1/-1}.node-summary{margin:14px 0}.detail-section{margin:15px 0}.node-detail>.button{align-self:end}.graph-toolbar{flex-wrap:wrap}.graph-toolbar>.text-link{font-size:10px}}
@media(max-width:600px){.view-switcher{display:flex;width:100%}.view-switcher .view-option{flex:1;padding:8px 6px;font-size:10px}.page-heading>.tag{display:none}.graph-toolbar .local-search{flex:1;min-width:135px}.graph-toolbar .local-search input{width:100%}.graph-toolbar select{max-width:145px}.graph-toolbar>.text-link{margin-top:5px}.node-detail{display:block;padding:22px}.lab-modal{padding:27px 22px}.lab-modal h2{font-size:20px}}
</style>
